// Simple endless runner targeting canvas with id="game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// Game config
const GRAVITY = 0.6;
const JUMP = -12;
const PLAYER_W = 30;
const PLAYER_H = 50;
const OBSTACLE_W = 30;
const OBSTACLE_GAP = 200; // distance between obstacles
const SPEED = 4;

let player = {x: 50, y: canvas.height - PLAYER_H, w: PLAYER_W, h: PLAYER_H, vy: 0, onGround: true};
let obstacles = [];
let frames = 0;
let score = 0;
let gameOver = false;

function spawnObstacle() {
  const height = Math.random() * (PLAYER_H * 2) + 20; // variable height
  obstacles.push({x: canvas.width, y: canvas.height - height, w: OBSTACLE_W, h: height});
}

function reset() {
  player.y = canvas.height - PLAYER_H; player.vy = 0; player.onGround = true;
  obstacles = [];
  frames = 0; score = 0; gameOver = false;
}

function update() {
  if (gameOver) return;
  frames++;
  // player physics
  player.vy += GRAVITY;
  player.y += player.vy;
  if (player.y + player.h >= canvas.height) {
    player.y = canvas.height - player.h;
    player.vy = 0;
    player.onGround = true;
  } else {
    player.onGround = false;
  }
  // obstacles movement
  obstacles.forEach(o => o.x -= SPEED);
  // remove off‑screen obstacles
  obstacles = obstacles.filter(o => o.x + o.w > 0);
  // spawn new obstacles periodically
  if (frames % Math.round(OBSTACLE_GAP / SPEED) === 0) spawnObstacle();
  // collision detection
  for (let o of obstacles) {
    if (player.x < o.x + o.w && player.x + player.w > o.x &&
        player.y < o.y + o.h && player.y + player.h > o.y) {
      gameOver = true;
      break;
    }
  }
  if (!gameOver) score = Math.floor(frames / 5);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // player
  ctx.fillStyle = '#0a84ff';
  ctx.fillRect(player.x, player.y, player.w, player.h);
  // obstacles
  ctx.fillStyle = '#ff3b30';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  // score
  ctx.fillStyle = '#000';
  ctx.font = '20px sans-serif';
  ctx.fillText('Score: ' + score, 10, 30);
  // game over
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    ctx.textAlign = 'left';
  }
}

function loop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}

// input handling
function jump() {
  if (player.onGround && !gameOver) {
    player.vy = JUMP;
    player.onGround = false;
  } else if (gameOver) {
    reset();
    requestAnimationFrame(loop);
  }
}

document.addEventListener('keydown', e => { if (e.code === 'Space') jump(); });
document.addEventListener('touchstart', jump);

// start game
requestAnimationFrame(loop);
